import sys
import pandas as pd

PATH = sys.argv[1] if len(sys.argv) > 1 else "budget.xlsx"


def to_number(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).replace("$", "").replace(",", "").strip()
    if s in ("", "-", "--", "n/a", "N/A"):
        return None
    try:
        return float(s)
    except ValueError:
        return None


sheets = pd.read_excel(PATH, sheet_name=None, header=None)
print("Sheets found:", list(sheets.keys()))

overall = 0.0
for name, df in sheets.items():
    print(f"\n--- Sheet: {name} ({df.shape[0]} rows x {df.shape[1]} cols) ---")
    print(df.to_string(max_rows=100, max_cols=20))

    best_col, best_count = None, 0
    for col in df.columns:
        cnt = df[col].apply(to_number).notna().sum()
        if cnt > best_count:
            best_col, best_count = col, cnt

    if best_col is None or best_count == 0:
        print("  (no numeric data)")
        continue

    total = 0.0
    excluded = []
    for idx in df.index:
        v = to_number(df.at[idx, best_col])
        if v is None:
            continue
        label = ""
        for c in df.columns:
            if c != best_col and pd.notna(df.at[idx, c]):
                label = str(df.at[idx, c])
                break
        if label.strip().lower() in ("total", "grand total", "total expenses", "sum"):
            excluded.append((label, v))
            continue
        total += v

    overall += total
    print(f"  Amount column: {best_col} ({best_count} numeric cells)")
    if excluded:
        print(f"  Excluded total-row value(s): {excluded}")
    print(f"  Sum of category amounts: {total:,.2f}")

print(f"\nTOTAL EXPENSES ACROSS ALL CATEGORIES: {overall:,.2f}")

